-- Explicit limited partner cutover: previous broad project grants do not become
-- object/contact disclosure grants. Internal and broker roles retain their rules.
create or replace function crm_classification_allowed(p_workspace uuid,p_class text,p_purpose text)
returns boolean language sql stable security invoker set search_path=pg_catalog,public as $$
 select p_workspace=nullif(current_setting('app.tenant_id',true),'')::uuid and p_purpose='crm_sales' and exists(
 select 1 from workspaces w join workspace_users u on u.workspace_id=w.id where w.id=p_workspace and u.id=nullif(current_setting('app.actor_id',true),'')::uuid and u.status='active' and u.product_role<>'external_partner'
 and((p_class='CUSTOMER_TENANT' and w.operating_model in('self_service_customer','managed_by_novalure','hybrid')) or(p_class='NOVALURE_INTERNAL' and w.operating_model='novalure_internal' and u.product_role in('platform_admin','novalureGrowth','novalureServiceOps','novalureAdmin','novalure_sales','novalure_onboarding','novalure_customer_success','novalure_operator'))))
$$;
create or replace function crm_project_access(p_workspace uuid,p_project uuid,p_write boolean default false)
returns boolean language sql stable security invoker set search_path=pg_catalog,public as $$
 select p_workspace=nullif(current_setting('app.tenant_id',true),'')::uuid and exists(select 1 from workspace_users u where u.workspace_id=p_workspace and u.id=nullif(current_setting('app.actor_id',true),'')::uuid and u.status='active' and u.product_role<>'external_partner' and(not p_write or u.role in('owner','admin','agent'))
 and(crm_workspace_manager(p_workspace) or exists(select 1 from project_pipeline_permissions g where g.workspace_id=p_workspace and g.project_id=p_project and g.user_id=u.id and g.can_read and(not p_write or g.can_edit_deals))))
$$;
create function crm_partner_actor(w uuid) returns boolean language sql stable set search_path=pg_catalog,public as $$
 select w=nullif(current_setting('app.tenant_id',true),'')::uuid and exists(select 1 from workspace_users u where u.workspace_id=w and u.id=nullif(current_setting('app.actor_id',true),'')::uuid and u.status='active' and u.product_role='external_partner' and u.role not in('owner','admin'))
$$;
create policy partner_no_generic_media on media_assets as restrictive for all to novalure_tenant_app using(
 current_user=pg_get_userbyid((select relowner from pg_class where oid='public.media_assets'::regclass)) or not exists(select 1 from workspace_users u where u.id=nullif(current_setting('app.actor_id',true),'')::uuid and u.workspace_id::text=media_assets.workspace_id and u.product_role='external_partner'));
create table crm_partner_property_grants (
 id uuid primary key default gen_random_uuid(),workspace_id uuid not null references workspaces(id),project_id uuid not null,property_id uuid not null,partner_id uuid not null,snapshot jsonb not null check(jsonb_typeof(snapshot)='object'),unit_ids jsonb not null check(jsonb_typeof(unit_ids)='array'),
 expires_at timestamptz not null,status text not null default 'active' check(status in('active','revoked')),revision integer not null default 1 check(revision>0),created_by uuid not null,updated_at timestamptz not null default now(),
 unique(workspace_id,partner_id,property_id),foreign key(workspace_id,project_id) references projects(workspace_id,id),foreign key(workspace_id,property_id) references seller_listings(workspace_id,id),foreign key(workspace_id,partner_id) references workspace_users(workspace_id,id),foreign key(workspace_id,created_by) references workspace_users(workspace_id,id)
);
create table crm_partner_lead_grants (
 id uuid primary key default gen_random_uuid(),workspace_id uuid not null references workspaces(id),project_id uuid not null,lead_id uuid not null,partner_id uuid not null,label text not null check(length(trim(label)) between 1 and 100),expires_at timestamptz not null,status text not null default 'active' check(status in('active','revoked')),revision integer not null default 1 check(revision>0),created_by uuid not null,updated_at timestamptz not null default now(),
 unique(workspace_id,partner_id,lead_id),foreign key(workspace_id,project_id,lead_id) references leads(workspace_id,project_id,id),foreign key(workspace_id,partner_id) references workspace_users(workspace_id,id),foreign key(workspace_id,created_by) references workspace_users(workspace_id,id)
);
create table crm_partner_requests (
 id uuid primary key,workspace_id uuid not null references workspaces(id),project_id uuid not null,property_grant_id uuid not null references crm_partner_property_grants(id),partner_id uuid not null,property_id uuid not null,unit_id uuid not null,lead_grant_id uuid references crm_partner_lead_grants(id),reference text not null check(length(trim(reference)) between 1 and 120),expires_at timestamptz not null,
 status text not null default 'pending' check(status in('pending','withdrawn','rejected','linked')),revision integer not null default 1,request_key uuid not null,request_hash text not null,reservation_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(workspace_id,partner_id,request_key),foreign key(workspace_id,project_id,unit_id) references property_units(workspace_id,project_id,id),foreign key(workspace_id,partner_id) references workspace_users(workspace_id,id),foreign key(workspace_id,property_id) references seller_listings(workspace_id,id),foreign key(workspace_id,project_id,reservation_id) references property_reservations(workspace_id,project_id,id)
);
create function crm_partner_property_allowed(g uuid) returns boolean language sql stable security definer set search_path=pg_catalog,public as $$
 select exists(select 1 from crm_partner_property_grants r where r.id=g and r.workspace_id=nullif(current_setting('app.tenant_id',true),'')::uuid and r.partner_id=nullif(current_setting('app.actor_id',true),'')::uuid and r.status='active' and r.expires_at>clock_timestamp() and crm_partner_actor(r.workspace_id))
$$;
do $$ declare relation text; begin foreach relation in array array['crm_partner_property_grants','crm_partner_lead_grants','crm_partner_requests'] loop
 execute format('alter table %I enable row level security',relation);execute format('alter table %I force row level security',relation);
 execute format('create policy partner_manager on %I for all to novalure_tenant_app using(crm_project_access(workspace_id,project_id,true) and crm_workspace_manager(workspace_id)) with check(crm_project_access(workspace_id,project_id,true) and crm_workspace_manager(workspace_id))',relation);
 execute format('create policy partner_owner_read on %I for select using(current_user=pg_get_userbyid((select relowner from pg_class where oid=%L::regclass)) and workspace_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',relation,'public.'||relation);
end loop; end $$;
create policy partner_own_property on crm_partner_property_grants for select to novalure_tenant_app using(crm_partner_actor(workspace_id) and partner_id=nullif(current_setting('app.actor_id',true),'')::uuid and status='active' and expires_at>clock_timestamp());
create policy partner_own_lead on crm_partner_lead_grants for select to novalure_tenant_app using(crm_partner_actor(workspace_id) and partner_id=nullif(current_setting('app.actor_id',true),'')::uuid and status='active' and expires_at>clock_timestamp());
create policy partner_own_request on crm_partner_requests for select to novalure_tenant_app using(crm_partner_actor(workspace_id) and partner_id=nullif(current_setting('app.actor_id',true),'')::uuid and crm_partner_property_allowed(property_grant_id));
create policy partner_insert_request on crm_partner_requests for insert to novalure_tenant_app with check(crm_partner_actor(workspace_id) and partner_id=nullif(current_setting('app.actor_id',true),'')::uuid and crm_partner_property_allowed(property_grant_id) and status='pending' and reservation_id is null and revision=1);
create policy partner_withdraw_request on crm_partner_requests for update to novalure_tenant_app using(crm_partner_actor(workspace_id) and partner_id=nullif(current_setting('app.actor_id',true),'')::uuid and crm_partner_property_allowed(property_grant_id) and status='pending') with check(status='withdrawn' and reservation_id is null);
create policy partner_share_owner_lock on crm_partner_property_grants for update using(current_user=pg_get_userbyid((select relowner from pg_class where oid='public.crm_partner_property_grants'::regclass)) and workspace_id=nullif(current_setting('app.tenant_id',true),'')::uuid) with check(current_user=pg_get_userbyid((select relowner from pg_class where oid='public.crm_partner_property_grants'::regclass)) and workspace_id=nullif(current_setting('app.tenant_id',true),'')::uuid);
create policy partner_inventory_owner_lock on property_units for update using(current_user=pg_get_userbyid((select relowner from pg_class where oid='public.property_units'::regclass)) and workspace_id=nullif(current_setting('app.tenant_id',true),'')::uuid) with check(current_user=pg_get_userbyid((select relowner from pg_class where oid='public.property_units'::regclass)) and workspace_id=nullif(current_setting('app.tenant_id',true),'')::uuid);
grant select,insert,update on crm_partner_property_grants,crm_partner_lead_grants,crm_partner_requests to novalure_tenant_app;

create function crm_partner_scope_guard() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$
declare g crm_partner_property_grants; begin
 if tg_table_name<>'crm_partner_requests' then
  if not crm_workspace_manager(new.workspace_id) or not crm_project_access(new.workspace_id,new.project_id,true) or not exists(select 1 from workspace_users u where u.id=new.partner_id and u.workspace_id=new.workspace_id and(new.status='revoked' or(u.status='active' and u.product_role='external_partner' and u.role not in('owner','admin')))) then raise exception using errcode='42501',message='An active limited partner and project manager are required'; end if;
  if new.created_by is distinct from nullif(current_setting('app.actor_id',true),'')::uuid then raise exception using errcode='23514',message='Share reviewer must match actor'; end if;
  if new.expires_at>clock_timestamp()+interval '1 year' then raise exception using errcode='23514',message='Partner shares require a limited expiry'; end if;
  if tg_table_name='crm_partner_property_grants' then
   if new.status='active' and not exists(select 1 from seller_listings p where p.workspace_id=new.workspace_id and p.project_id=new.project_id and p.id=new.property_id) then raise exception using errcode='23514',message='Property scope mismatch'; end if;
   if new.snapshot-array['title','city','countryCode','areaSqm','rooms','price']<>'{}'::jsonb or jsonb_typeof(new.snapshot->'title')<>'string' or jsonb_typeof(new.snapshot->'city')<>'string' or new.snapshot->>'countryCode' not in('AT','DE','ES','IE') or jsonb_typeof(new.snapshot->'areaSqm')<>'number' or jsonb_typeof(new.snapshot->'rooms')<>'number' then raise exception using errcode='23514',message='Only reviewed public property fields may enter partner snapshots'; end if;
  end if;
 else
  select * into g from crm_partner_property_grants where id=new.property_grant_id and workspace_id=new.workspace_id and project_id=new.project_id and property_id=new.property_id and partner_id=new.partner_id for update;
  if not found or g.status<>'active' or g.expires_at<=clock_timestamp() or not exists(select 1 from jsonb_array_elements_text(g.unit_ids) u where u=new.unit_id::text) then raise exception using errcode='23514',message='Current object share and selected unit are required'; end if;
  if tg_op='INSERT' and(new.expires_at<=clock_timestamp() or new.expires_at>least(g.expires_at,clock_timestamp()+interval '7 days')) then raise exception using errcode='23514',message='Nonbinding request deadline must be within seven days and share expiry'; end if;
  if (tg_op='INSERT' or new.status='linked') and new.lead_grant_id is not null and not exists(select 1 from crm_partner_lead_grants l where l.id=new.lead_grant_id and l.workspace_id=new.workspace_id and l.project_id=new.project_id and l.partner_id=new.partner_id and l.status='active' and l.expires_at>clock_timestamp()) then raise exception using errcode='23514',message='Separate active lead share required'; end if;
  if new.reservation_id is not null and not exists(select 1 from property_reservations r where r.id=new.reservation_id and r.workspace_id=new.workspace_id and r.project_id=new.project_id and r.unit_id=new.unit_id) then raise exception using errcode='23514',message='Linked reservation must belong to the requested unit'; end if;
  if tg_op='INSERT' then
   perform id from property_units where id=new.unit_id and workspace_id=new.workspace_id and project_id=new.project_id and status='available' for update;
   if not found then raise exception using errcode='23514',message='Unit is no longer available'; end if;
   perform pg_advisory_xact_lock(hashtextextended(new.workspace_id::text||new.partner_id::text||new.unit_id::text,0));
   if exists(select 1 from crm_partner_requests r where r.workspace_id=new.workspace_id and r.partner_id=new.partner_id and r.unit_id=new.unit_id and r.status='pending' and r.expires_at>clock_timestamp()) then raise exception using errcode='23505',message='Partner already has a current nonbinding request for this unit'; end if;
  end if;
  if tg_op='UPDATE' and(new.workspace_id<>old.workspace_id or new.project_id<>old.project_id or new.property_grant_id<>old.property_grant_id or new.partner_id<>old.partner_id or new.property_id<>old.property_id or new.unit_id<>old.unit_id or new.lead_grant_id is distinct from old.lead_grant_id or new.reference<>old.reference or new.expires_at<>old.expires_at or new.request_key<>old.request_key or new.request_hash<>old.request_hash or new.created_at<>old.created_at) then raise exception using errcode='23514',message='Partner request identity is immutable'; end if;
 end if;
 if tg_op='UPDATE' and new.revision<>old.revision+1 then raise exception using errcode='23514',message='Share/request revision must advance'; end if;
 return new;
end $$;
do $$ declare relation text; begin foreach relation in array array['crm_partner_property_grants','crm_partner_lead_grants','crm_partner_requests'] loop execute format('create trigger partner_scope_guard before insert or update on %I for each row execute function crm_partner_scope_guard()',relation); end loop; end $$;

-- Authoritative live inventory/status metadata for the projection, never direct
-- runtime access to the source tables or to contact/financial/proof fields.
do $$ declare relation text; begin foreach relation in array array['seller_listings','property_units','leads','property_reservations','workspace_users'] loop execute format('create policy partner_projection_owner on %I for select using(current_user=pg_get_userbyid((select relowner from pg_class where oid=%L::regclass)) and workspace_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',relation,'public.'||relation); end loop; end $$;
create function crm_partner_projection() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$
declare w uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;a uuid:=nullif(current_setting('app.actor_id',true),'')::uuid;result jsonb;begin
 if not crm_partner_actor(w) then raise exception using errcode='42501',message='Limited partner identity required'; end if;
 select jsonb_build_object('properties',coalesce((select jsonb_agg(jsonb_build_object('grantId',g.id,'propertyId',g.property_id,'projectId',g.project_id,'snapshot',g.snapshot||case when exists(select 1 from seller_listings live where live.id=g.property_id and live.workspace_id=g.workspace_id and live.project_id=g.project_id and live.price_visibility='publish_price') then '{}'::jsonb else '{"price":null}'::jsonb end,'expiresAt',g.expires_at,'units',coalesce((select jsonb_agg(jsonb_build_object('id',u.id,'number',u.unit_number,'areaSqm',u.area_sqm,'rooms',u.rooms,'status',u.status) order by u.unit_number) from property_units u join seller_listings p on p.id=g.property_id and p.workspace_id=g.workspace_id and p.project_id=g.project_id where u.workspace_id=g.workspace_id and u.project_id=g.project_id and u.id::text in(select jsonb_array_elements_text(g.unit_ids)) and(u.metadata->>'sellerListingId'=p.id::text or u.id=p.unit_id) and coalesce(u.metadata->>'hidden','false')<>'true'),'[]'::jsonb))) from(select * from crm_partner_property_grants where workspace_id=w and partner_id=a order by updated_at desc limit 200) g where g.workspace_id=w and g.partner_id=a and g.status='active' and g.expires_at>clock_timestamp()),'[]'::jsonb),
 'leads',coalesce((select jsonb_agg(jsonb_build_object('grantId',g.id,'projectId',g.project_id,'label',g.label,'status',l.status,'expiresAt',g.expires_at)) from(select * from crm_partner_lead_grants where workspace_id=w and partner_id=a order by updated_at desc limit 200) g join leads l on l.id=g.lead_id and l.workspace_id=g.workspace_id and l.project_id=g.project_id where g.workspace_id=w and g.partner_id=a and g.status='active' and g.expires_at>clock_timestamp()),'[]'::jsonb),
 'requests',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'propertyId',r.property_id,'unitId',r.unit_id,'reference',r.reference,'expiresAt',r.expires_at,'status',case when r.status='pending' and r.expires_at<=clock_timestamp() then 'expired' else r.status end,'revision',r.revision,'reservationStatus',(select status from property_reservations pr where pr.id=r.reservation_id and pr.workspace_id=r.workspace_id and pr.project_id=r.project_id))) from(select * from crm_partner_requests where workspace_id=w and partner_id=a order by created_at desc limit 200) r where r.workspace_id=w and r.partner_id=a and crm_partner_property_allowed(r.property_grant_id)),'[]'::jsonb)) into result;
 return result;
end $$;
revoke all on function crm_partner_projection(),crm_partner_scope_guard(),crm_partner_property_allowed(uuid),crm_partner_actor(uuid) from public;
grant execute on function crm_partner_projection(),crm_partner_property_allowed(uuid),crm_partner_actor(uuid) to novalure_tenant_app;
